# owner: platform
"""Contact sheet rows for substitute teachers."""

from typing import List, Tuple

from rosterkit.models import Student


# ---
def contact_rows(students: List[Student]) -> List[str]:
    """Name, section and email per row, sorted by name."""
    _check_students(students)
    ordered = sorted(students, key=_name_key)
    widths = _widths(ordered)
    return [_format_row(item, widths) for item in ordered]


def _check_students(students: List[Student]) -> None:
    if not students:
        raise ValueError("contact sheet needs students")
    missing = [item for item in students if not item.email]
    if missing:
        names = [item.display_name for item in missing]
        raise ValueError(f"no email for {', '.join(names)}")


def _name_key(student: Student) -> str:
    return student.display_name.casefold()


def _widths(students: List[Student]) -> Tuple[int, int]:
    names = [item.display_name for item in students]
    sections = [item.section for item in students]
    return max(map(len, names)), max(map(len, sections))


def _format_row(
    student: Student, widths: Tuple[int, int]
) -> str:
    name_width, section_width = widths
    name = student.display_name.ljust(name_width)
    section = student.section.ljust(section_width)
    return f"{name}  {section}  {student.email}"
